  <main class="container">
    <h1>Contact Support</h1>
    <p class="subtitle">Please fill out the form below. Required fields are marked with an asterisk (<span aria-hidden="true" class="required-marker">*</span>).</p>

    <div id="status-container" role="status"></div>

    <form id="contactForm" novalidate>
      <div class="form-field">
        <label for="fullName">Full name <span aria-hidden="true" class="required-marker">*</span></label>
        <input id="fullName" name="fullName" type="text" required autocomplete="name">
        <div id="fullName-error" class="error-message" hidden></div>
      </div>

      <div class="form-field">
        <label for="email">Email address <span aria-hidden="true" class="required-marker">*</span></label>
        <input id="email" name="email" type="email" required autocomplete="email">
        <div id="email-error" class="error-message" hidden></div>
      </div>

      <div class="form-field">
        <label for="phone">Phone number (optional)</label>
        <p id="phone-help" class="help-text">Format: 123-456-7890</p>
        <input id="phone" name="phone" type="tel" autocomplete="tel" aria-describedby="phone-help">
        <div id="phone-error" class="error-message" hidden></div>
      </div>

      <button type="submit">Submit Request</button>
    </form>
  </main>

  <script>
    document.addEventListener('DOMContentLoaded', () => {
      const form = document.getElementById('contactForm');
      const statusContainer = document.getElementById('status-container');

      const fields = [
        {
          id: 'fullName',
          validate: (value) => {
            if (!value.trim()) {
              return 'Error: Full name is required.';
            }
            return '';
          }
        },
        {
          id: 'email',
          validate: (value) => {
            if (!value.trim()) {
              return 'Error: Email address is required.';
            }
            // Basic email validation
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailRegex.test(value)) {
              return 'Error: Enter a valid email like name@example.com.';
            }
            return '';
          }
        },
        {
          id: 'phone',
          validate: (value) => {
            if (!value.trim()) {
              return ''; // Optional field
            }
            // Validate format: 123-456-7890
            const phoneRegex = /^\d{3}-\d{3}-\d{4}$/;
            if (!phoneRegex.test(value)) {
              return 'Error: Phone number must be in the format 123-456-7890.';
            }
            return '';
          }
        }
      ];

      function clearError(fieldId) {
        const input = document.getElementById(fieldId);
        const errorDiv = document.getElementById(`${fieldId}-error`);

        input.removeAttribute('aria-invalid');
        errorDiv.textContent = '';
        errorDiv.setAttribute('hidden', '');

        // Manage aria-describedby
        const describedBy = input.getAttribute('aria-describedby') || '';
        const errorId = `${fieldId}-error`;
        if (describedBy.includes(errorId)) {
          const newDescribedBy = describedBy.replace(errorId, '').trim();
          if (newDescribedBy) {
            input.setAttribute('aria-describedby', newDescribedBy);
          } else {
            input.removeAttribute('aria-describedby');
          }
        }
      }

      function showError(fieldId, message) {
        const input = document.getElementById(fieldId);
        const errorDiv = document.getElementById(`${fieldId}-error`);

        input.setAttribute('aria-invalid', 'true');
        errorDiv.textContent = message;
        errorDiv.removeAttribute('hidden');

        // Manage aria-describedby
        const describedBy = input.getAttribute('aria-describedby') || '';
        const errorId = `${fieldId}-error`;
        if (!describedBy.includes(errorId)) {
          input.setAttribute('aria-describedby', describedBy ? `${describedBy} ${errorId}` : errorId);
        }
      }

      // Real-time validation after form submission is attempted
      let formSubmittedOnce = false;

      fields.forEach(field => {
        const input = document.getElementById(field.id);

        // Clear error on input
        input.addEventListener('input', () => {
          if (formSubmittedOnce) {
            const error = field.validate(input.value);
            if (error) {
              showError(field.id, error);
            } else {
              clearError(field.id);
            }
          }
        });

        // Validate on blur
        input.addEventListener('blur', () => {
          if (formSubmittedOnce) {
            const error = field.validate(input.value);
            if (error) {
              showError(field.id, error);
            } else {
              clearError(field.id);
            }
          }
        });
      });

      form.addEventListener('submit', (e) => {
        e.preventDefault();
        formSubmittedOnce = true;

        let isValid = true;
        let firstInvalidInput = null;

        // Clear previous status message
        statusContainer.innerHTML = '';

        fields.forEach(field => {
          const input = document.getElementById(field.id);
          const error = field.validate(input.value);

          if (error) {
            showError(field.id, error);
            isValid = false;
            if (!firstInvalidInput) {
              firstInvalidInput = input;
            }
          } else {
            clearError(field.id);
          }
        });

        if (!isValid) {
          firstInvalidInput.focus();
        } else {
          // Form is valid, simulate successful submission
          form.reset();
          formSubmittedOnce = false; // Reset the state
          fields.forEach(field => clearError(field.id)); // Clear any residual error state

          // Focus management: Status messages don't move focus, 
          // but we announce the success using the status role
          statusContainer.innerHTML = '<div class="status-message">Success: Your request has been sent.</div>';
        }
      });
    });
  </script>
