           id: 'phone',
           validate: (value) => {
             if (!value.trim()) {
               return ''; // Optional field
             }
             // Validate format: 123-456-7890
             const phoneRegex = /^\d{3}-\d{3}-\d{4}$/;
             if (!phoneRegex.test(value)) {
               return 'Error: Phone number must be in the format 123-456-7890.';
             }
             return '';
